window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["pl"]={"p":["index.html","theming.html","widgets.html"],"n":["Przegląd","Motywy","Widżety"],"d":[[0,"showcase","Jak to wygląda w grze",0,"Presety średniowieczny i sci-fi — karty postaci, ekwipunek i zadania; formularze, siatki i karty pytań; kanciaste panele i sterowanie dotykowe. Przełączenie presetu to jedna linijka kodu. Średniowieczny — postać, ekwipunek i zadania Średniowieczny — formularze, siatki i karty pytań Sci-fi — kanciaste panele i sterowanie dotykowe Wszystkie sześć presetów i jak je przełączać →","",-1],[0,"what","Co zdejmuje z twoich barków",0,"Najwięcej czasu w interfejsie gry pochłania nie kształt przycisku — tylko wszystko to, co rozjeżdża się między urządzeniami. gohud ogarnia to rozjeżdżanie w jednym miejscu. Każdy wymiar to token Odstępy, narożniki i rozmiary tekstu wywołuje się po nazwie, a nie wpisuje liczbami. Podmień motyw, a cały ekran ruszy razem z nim. Rozmiar widoczny ≠ rozmiar klikalny Przycisk zamknięcia wygląda na 36 dp, ale jego obszar dotyku ma 48 dp. Tam, gdzie ciasno ułożone sloty zachodzą na siebie, naciśnięcie przejmuje ten, którego środek jest bliżej. Wycięcia i klawiatury Elementy HUD siedzą wewnątrz bezpiecznego obszaru, a pole wprowadzania unosi się ponad klawiaturę ekranową, gdy ta się pojawi. Wstecz zamyka jedną rzecz Escape i androidowy przycisk Wstecz zamykają tylko wierzchnią powierzchnię. Ułożone na sobie okna nie znikają razem. Powiadomienia nie kradną wejścia Naciśnij przez snackbar, a odbierze to przycisk pod spodem. Fokus też nie zostaje zabrany. O ikony prosi się po nazwie Widżety znają tylko GoIconSet.CLOSE. Podmień zestaw, a zmienią się wszystkie rysunki bez ruszania jednej linijki kodu. Sześć wyglądów, jedna linijka GoUi.use_preset() podmienia motyw, skórkę i ikony naraz — zaokrąglone, ścięte sci-fi albo kute średniowieczne ramy. Czytelność z pomiaru Każdy motyw jest sprawdzany względem WCAG, łącznie ze stanami przycisków i półprzezroczystymi panelami HUD na czystej bieli i czystej czerni. Wszystko działa bez włączania wtyczki. Włączenie dokłada autoload GoRuntime, który śledzi rozmiar okna, skalę dp i wysokość klawiatury, oraz ustawienia projektu dla zasobu konfiguracji i presetu — to udogodnienia, nie wymagania.","",-1],[0,"install","Instalacja",0,"Wrzuć folder dodatku do swojego projektu. Nie ma nic więcej do ustawienia.","",-1],[0,"from-the-asset-store-or-a-release-zip","Z Asset Store albo z ZIP-a wydania",1,"Rozpakuj do katalogu głównego projektu, tak aby powstało res://addons/gohud/. To wszystko. Opcjonalnie włącz Projekt → Ustawienia projektu → Wtyczki → gohud.","",2],[0,"as-a-git-submodule","Jako submoduł git",1,"Katalog główny repozytorium jest folderem dodatku, więc ląduje dokładnie tam, gdzie Godot się go spodziewa. Edytuj na miejscu, commituj i wypychaj wewnątrz addons/gohud, a potem zacommituj wskaźnik submodułu w swojej grze. Wymagany jest Godot 4.6 lub nowszy. gohud korzysta z API wprowadzonych w 4.5 (DPITexture, FoldableContainer, właściwości dostępności), więc na czymkolwiek starszym nie przechodzi nawet parsowania. 4.6 to wspierane minimum, zapisane w GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # opcjonalnie: przypnij tag albo commit",2],[0,"start","Szybki start",0,"Każdy widżet to .new() i add_child() — bez plików scen, bez autoloadu.","",-1],[0,"pick-a-look-before-building-ui-optional","Wybierz wygląd, zanim zbudujesz UI (opcjonalnie)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # gdy to pominiesz, użyty zostanie default_dark",5],[0,"a-confirmation-you-await","Potwierdzenie, na które czekasz przez await",1,"Przekaż destructive = true (ostatni argument), a przycisk potwierdzenia zostanie narysowany jako wypełniony przycisk niebezpieczeństwa.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Usuń zapis\", \"Tego nie da się cofnąć.\"): delete_save()",5],[0,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Dolny arkusz z przyklejonym polem wyszukiwania i stopką",1,"Dlaczego przyklejone wiersze są oddzielone od przewijanego ciała. Wsadź potwierdzenie i anulowanie do body, a długa lista wypchnie je poza ekran. footer() jest widoczna zawsze.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Ekwipunek\") sheet.toolbar().add_child(GoStyle.line_edit(\"Szukaj…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Zamknij\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",5],[0,"a-hud-corner","Narożnik HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",5],[0,"content-that-keeps-clear-of-the-hud","Treść, która omija HUD",1,"Każdy prostokąt omijany jest w tym kierunku, który kosztuje najmniej powierzchni — w dół na telefonie w pionie, na bok w poziomie. Jak HUD omija sam siebie →","form.avoid_hud = true # omijaj każdy widoczny GoHudAnchor joystick_anchor.reserve_space = false # …poza tymi, które pojawiają się dopiero pod palcem notice_anchor.avoid_peers = true # powiadomienie osiada pod stałym HUD, zamiast go zasłaniać",5],[0,"presets","Zmień wygląd — kolory i kształt",0,"Motyw potrafi przestylizować tylko to, co rysuje silnik. Zaokrąglone narożniki to jedyne narożniki, jakie ma StyleBoxFlat, a joystick, szybkie sloty i wskazówka instruktażowa są rysowane kodem — więc sam motyw nigdy nie zmieni ich kształtu. Dlatego gohud dostarcza presety: motyw, skórkę i zestaw ikon dobrane jako jedna całość. Preset Wygląd default_dark Oryginalny gohud — zaokrąglone narożniki, miękki niebieski akcent default_light Te same kształty na jasnej palecie scifi_dark Ścięte narożniki, cyjanowe neonowe krawędzie i poświata, sześciokątny joystick, ramki celownicze scifi_light Te same kanciaste kształty w jasnej palecie rysunku technicznego medieval_dark Ciemne żelazo i skóra, ramy ze starego złota, nity, grawerowane ikony, nagłówki Cinzel medieval_light Pergamin, atrament i brąz z tymi samymi kutymi ramami default_dark — zaokrąglone narożniki, miękki niebieski akcent default_light — te same kształty, jasna paleta scifi_dark — ścięte narożniki, cyjanowy neon scifi_light — te same kanciaste kształty, paleta rysunku technicznego Te cztery to ten sam ekran galerii. Nie różni się ani linijka kodu — tylko nazwa presetu. Narożniki przycisków, kształty przełączników, wiersze list i obramowania pól wprowadzania ruszają się razem.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # motyw, skórka i ikony naraz",-1],[0,"medieval-collection","Kolekcja średniowieczna",1,"medieval_dark łączy żelazo i skórę ze starym złotem; medieval_light używa pergaminu i atramentu. Ramy menu niosą nit i mały ornament narożny, podczas gdy stale widoczny HUD pozostaje spokojny; 16 grawerowanych ikon przerysowuje nazwy przedmiotów, a dołączonej czcionki Cinzel używają wyłącznie tytuły i podtytuły. medieval_dark — żelazo i skóra medieval_light — pergamin i atrament Oba zrzuty to examples/medieval/medieval.tscn, zbudowane ze standardowych widżetów. Przewodnik po średniowieczu i jak zrobić własne królestwo →","",11],[0,"the-same-screen-on-a-phone-and-on-a-desktop","Ten sam ekran na telefonie i na komputerze",1,"Zrzuty galerii to telefon w pionie. Poniżej ten sam kod w 1280×800 — treść zatrzymuje się na czytelnej szerokości (480 dp) i centruje, a HUD zostaje w narożnikach. Formularz omija pływające elementy HUD, ale nie rusza się, gdy już ich nie dotyka: przesuwanie na siłę zrzuciłoby treść ze środka na szerokim ekranie. default_dark · 1280×800 scifi_dark · 1280×800","",11],[0,"the-same-sheet-a-different-look","Ten sam arkusz, inny wygląd",1,"Domyślny — zaokrąglona karta, przyklejony wiersz wyszukiwania i stopka Sci-fi — górna krawędź akcentu, ścięte narożniki, poświata Wybierz jeden w Ustawieniach projektu → gohud → Theme → Preset albo ustaw GoConfig.preset. Jawne wypełnienie theme, skin lub icons wygrywa z presetem, więc możesz wziąć preset i nadpisać tylko jedną z tych rzeczy. Nowy motyw to jeden plik JSON. new_theme.py kingdom --from medieval_dark zapisuje paletę, która wypisuje wprost każdą odziedziczoną wartość; make_theme.py kingdom buduje motyw, jego grafiki kontrolek i pokrętła skórki, a preset pojawia się w selektorze. Każde ustawienie i pokrętło →","",11],[0,"skin","Skórki — tam, gdzie motyw nie sięga",0,"Skórka posiada joystick, lica szybkich slotów, pierścień wskazówki instruktażowej, chipy, szkielety, alerty, separatory i nagłówki sekcji. Odziedzicz po niej i nadpisz tylko to, co chcesz zmienić. Klasa Jakie kształty potrafi zrobić GoStyleBoxCut Ukośnie ścięte narożniki (fazowanie), jedna pogrubiona krawędź akcentu, zewnętrzna poświata GoStyleBoxBracket Same znaczniki narożne, bez zamykania treści w ramie GoStyleBoxMedieval Kuta rama z nitami, grawerem w narożnikach, podświetleniem fazy i fakturą materiału Wszystkie trzy serializują się do zasobu Theme — i to właśnie pozwala motywowi zmieniać kształt, a nie tylko kolor. GoSkinSciFi i GoSkinMedieval to dostarczone podklasy. GoStyle.box() zawsze zwraca StyleBoxFlat, ponieważ kod wywołujący go otrzymuje i dostraja bg_color albo corner_radius. Gdy własny kształt ma przetrwać, użyj GoStyle.surface().","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Widżety",0,"Wszystkie elementy w jednej tabeli. Każdy z nich szczegółowo → Klasa Klasa bazowa Co robi GoSurface Control Powłoka pływającej karty — położenie na środku, u dołu albo przy kontrolce, przyklejony nagłówek i stopka, przewijane ciało, zmiana rozmiaru przeciągnięciem GoSheet CanvasLayer Strony wznoszące się od dołu, na własnej warstwie, więc siedzą ponad HUD GoDialogs Node Potwierdzenia i alerty, na które czekasz przez await; destructive dla działań nieodwracalnych GoForm MarginContainer Formularze z ograniczoną szerokością, omijające klawiaturę ekranową, a z avoid_hud także HUD GoScroll ScrollContainer Przewijanie dotykiem; pasek przewijania chowa się w marginesie wewnętrznym karty GoNotice PanelContainer Snackbar, który nie zabiera ani wejścia, ani fokusu GoPromptCard PanelContainer Pytanie, które nie blokuje gry GoCoachMark Control Przewodnik wskazujący prawdziwe kontrolki; naciśnięcie celu przesuwa go dalej GoHudAnchor Control Przypina elementy HUD do jednego z dziewięciu miejsc w bezpiecznym obszarze GoBar Control Paski zdrowia, many i doświadczenia z wygładzonymi zmianami GoSlot Button Szybki slot — ikona, liczba, odnowienie i skrót na jednym licu GoJoystick Control Wirtualny joystick w trybie stałym, podążającym albo względnym GoIconButton Button Wygląda na mały, naciska się duży GoStyle statyczna Przyciski, wiersze list, pola wprowadzania, chipy, tabele, zakładki i więcej, tworzone w jeden spójny sposób","",-1],[0,"examples","Przykłady, które możesz uruchomić",0,"Trzy sposoby, by zobaczyć gohud przed napisaniem linijki — żaden nie potrzebuje serwera ani autoloadu. Przykład Jak otworzyć Co pokazuje Galeria examples/gallery/gallery.tscn · F6 Każdy widżet, selektor każdego zainstalowanego presetu i pełny zestaw ikon Średniowiecze examples/medieval/medieval.tscn · F6 Karta postaci, sakwa i dziennik zadań; przyciski przełączają żelazo i pergamin oraz otwierają szczegóły przedmiotu Aplikacja demo cd examples/demo && godot Ekran główny otwierający galerię, 15-rozdziałowy przewodnik, ekran pokazowy i wygląd średniowieczny, z żywymi widżetami i jedną kartą na klasę Aplikacja demo nie potrzebuje żadnej konfiguracji: jeśli brakuje dowiązania do dodatku albo pamięci podręcznej importu, mówi o tym, naprawia folder i otwiera się ponownie. Jej ekran główny otwiera każdy przykład wewnątrz tego samego okna — naciśnij 1–4 albo kliknij wiersz, a pasek u góry zabierze cię z powrotem. W przewodniku C przełącza tryb kinowy, F11 pełny ekran, Spacja pauzuje (albo odtwarza bieżący widżet w trybie eksploracji), strzałki zmieniają rozdziały, a Escape wraca na ekran startowy. Używasz agenta AI do kodowania? Otwórz wszystkie trzy jednym poleceniem →","cd examples/demo && godot # ekran główny; dowiązania i import przy pierwszym uruchomieniu bash examples/demo/run.sh # ta sama aplikacja, z katalogu głównego dodatku bash examples/demo/run.sh -- --open=gallery # pomiń ekran główny bash examples/demo/run.sh -- --explore=surfaces # otwórz od razu na jednym rozdziale przewodnika bash examples/demo/run.sh --record /tmp/gohud-demo.avi # nagranie przewodnika w 1080p / 60 kl./s",-1],[0,"ai","Otwórz to z poziomu agenta AI",0,"gohud dostarcza wtyczkę do Claude Code z poleceniami slash. Wpisz jedno, a galeria albo demo otworzy się we własnym oknie Godota — bez uruchamiania edytora, bez szukania sceny.","",-1],[0,"install-the-commands-once","Zainstaluj polecenia raz",1,"Inni agenci, na przykład Codex, mogą użyć tej samej umiejętności: skopiuj skills/gohud z tego repozytorium do folderu umiejętności agenta.","claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud # potem zrestartuj Claude Code",18],[0,"gohud-preview-the-widget-gallery","/gohud:preview — galeria widżetów",1,"Otwiera galerię: każdy widżet, selektor wszystkich sześciu presetów i pełny zestaw ikon. Wpisz to wewnątrz swojego projektu Godota, a użyje twojego addons/gohud; bez niego użyje kopii dołączonej do wtyczki albo świeżego klona. Działa w jednorazowym projekcie-piaskownicy, więc twoje autoloady i pamięć podręczna importu zostają nietknięte, a okno pozostaje otwarte, dopóki go nie zamkniesz.","",18],[0,"gohud-preview-demo-the-15-chapter-guided-tour","/gohud:preview demo — 15-rozdziałowy przewodnik",1,"Otwiera demo na ekranie startowym. Start demo odtwarza przewodnik z prawdziwym wejściem; Explore widgets pozwala wypróbować jeden widżet ręcznie. Klawisze wymienione w sekcji Przykłady działają też tutaj.","",18],[0,"many-other-commands","Wiele innych poleceń",1,"Polecenie Co robi /gohud:preview medieval Karta postaci, sakwa i dziennik zadań w presetach średniowiecznych /gohud:preview demo --explore hud Demo otwarte od razu na jednym rozdziale — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark Galeria w jednym presecie; dodaj --phone, by dostać okno telefonu 390×844, albo --size 1920x1080 dla dowolnego rozmiaru /gohud:preview res://ui/main_menu.tscn Scena z twojego własnego projektu, uruchomiona wewnątrz tego projektu /gohud:preview list Każdy cel, identyfikator presetu i klucz rozdziału demo /gohud:preview gallery --check Bezokienny test dymny w trybie headless — kończy się niepowodzeniem przy błędach skryptu /gohud:features Każda funkcja, pogrupowana, po jednej linijce kodu /gohud:features hud Jeden obszar w głąb — surfaces hud style theming icons i18n accessibility config Albo po prostu poproś. Umiejętność uczy agenta całego API gohud, więc zwykłe prośby też działają — „Zbuduj menu pauzy w gohud”. Gdy jest zainstalowana jako zwykła umiejętność w ~/.claude/skills/gohud, polecenia biorą spację: /gohud preview demo, /gohud features. Podglądy potrzebują Godota 4.6 lub nowszego w twoim PATH albo przekazania --godot /path/to/godot.","",18],[0,"readable","Czytelność się mierzy, a nie ocenia na oko",0,"„Ładne” to kwestia gustu; „czytelne” da się zmierzyć. Blady szary tekst wygląda dobrze na dobrym monitorze i znika na telefonie w słońcu — wybieranie na oko prędzej czy później to gwarantuje. Każda para kolorów i etykieta każdego stanu przycisku na panelu, na którym leży, jest mierzona względem WCAG, we wszystkich sześciu motywach. Półprzezroczyste kolory są najpierw składane na swoim prawdziwym tle — mierzenie ich wprost daje lepszy współczynnik, niż pokazuje ekran. Kolory tekstu są więc wyprowadzane, a nie wybierane: builder bierze wpis z palety jako punkt wyjścia i przesuwa jego jasność, aż przekroczy próg na każdej powierzchni, na której może wylądować. Zmień paletę, a kontrast pójdzie za nią. Zasady i pułapki, które za nimi stoją →","python3 addons/gohud/tools/check_contrast.py",-1],[0,"develop","Kontrole, wydania i ta strona",0,"Jeden punkt wejścia uruchamia wszystkie kontrole; każda część widzi coś, czego nie widzą pozostałe. Kontrola Co wyłapuje run_tests.sh w czterech rozmiarach ekranu Zachowanie i układ widżetów, pozycje RTL, fokus klawiatury, kontrast skórki w czasie działania, każdy preset new_project_check.sh Ukryte zależności od projektu-gospodarza; z --zip wydanie w postaci wysyłkowej, z --export build webowy check_contrast.py Kontrast WCAG każdego pliku motywu, wliczając stany przycisków i półprzezroczyste panele check_generated.py · check_scaffold.sh Wygenerowane motywy zgadzają się ze swoimi paletami; jednorazowy motyw buduje się i przechodzi kontrolę kontrastu check_package.py Podbicia wersji, przenoszenie wpisów changelogu i zawartość ZIP-a, w kopiach tymczasowych check_site.py Linki tej strony, kotwice, język stron, słowniczek i tabele pokręteł Ostatni zapisany przebieg — 2026-09-13, Godot 4.7.2, macOS, renderer Compatibility. 438 z 438 kontroli w 390×844, 844×390, 768×1024 i 1280×800 w pustym projekcie; ponownie 438 z 438 z autoloadem GoRuntime; eksport webowy; zero niepowodzeń kontrastu w sześciu motywach. Godot 4.6 ani fizyczne urządzenia z Androidem czy iOS nie były częścią tego przebiegu.","bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Wydawanie wersji",1,"Udany przebieg aktualizuje razem plugin.cfg, GoUi.VERSION i CHANGELOG.md, przenosząc notatki z sekcji Unreleased do datowanego wpisu. Nieudany przebieg nie zmienia niczego, a istniejący ZIP nigdy nie jest nadpisywany. ZIP pomija tę witrynę, testy i narzędzia.","bash addons/gohud/tools/package.sh # 1.0.1 → 1.0.2 · builds/1.0.2/gohud-1.0.2.zip bash addons/gohud/tools/package.sh --increase-minor-version # 1.0.1 → 1.1.0",24],[0,"this-site","Ta witryna",1,"Strony to zwykły HTML w www/ — angielski w katalogu głównym, koreański w ko/. Workflow GitHub Actions publikuje ten folder jako korzeń witryny.","python3 addons/gohud/tools/make_site.py # słowniczek i tabele pokręteł skórek, generowane ze źródeł python3 addons/gohud/tools/check_site.py # linki, kotwice, język, słowniczek, generowane tabele bash addons/gohud/tools/site_shots.sh /tmp/shots # zrzuty każdej strony na komputerze i telefonie",24],[1,"layers","Trzy warstwy",0,"Preset spina wszystkie trzy. Pola, które zostawisz puste, wracają do wartości domyślnych. Warstwa Decyduje o Jak to zmieniasz Theme Kolory, rozmiary, skala tekstu i kształt wszystkiego, co rysuje silnik — panele przycisków, pola wprowadzania, zakładki, grafiki przełączników Napisz własny .tres albo wygeneruj go przez tools/make_theme.py GoSkin Kształt wszystkiego, co rysuje kod — joysticka, lic szybkich slotów, pierścienia wskazówki instruktażowej, chipów, szkieletów, separatorów, nagłówków sekcji Odziedzicz po niej i nadpisz tylko te metody, na których ci zależy GoIconSet Ikony po nazwie — 84 domyślne rysunki albo 16 grawerowanych rysunków zestawu średniowiecznego nałożonych na nie. Pakiet tekstur albo font ikon; kod wywołujący jest w obu przypadkach identyczny Dostarcz zestaw albo nadpisz tylko kilka nazw Dlaczego sam motyw nie wystarcza. Zaokrąglony to jedyny narożnik, jaki ma StyleBoxFlat — ustaw promień na zero, a dostaniesz kąt prosty; pomiędzy nie ma nic. Ukośnie ścięte narożniki, pojedyncza pogrubiona krawędź, zewnętrzna poświata: silnik nie rysuje żadnej z tych rzeczy. A joystick i wskazówka instruktażowa są rysowane w _draw(), gdzie motyw nie sięga w ogóle.","",-1],[1,"pick","Wybór presetu",0,"Ta jedna linijka podmienia motyw, skórkę i ikony. Z poziomu edytora użyj Ustawienia projektu → Gohud → Theme → Preset; z zasobu ustawień — GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[1,"keeping-one-field-your-own","Zostawić jedno pole po swojemu",1,"Jawne ustawienie theme, skin lub icons wygrywa z presetem.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # twoje ikony, cała reszta z presetu",28],[1,"the-six-built-in-presets","Sześć wbudowanych presetów",1,"Preset Panele Skórka · ikony default_dark · default_light Zaokrąglone panele StyleBoxFlat na stopniowanej skali cieni; przyciski główne unoszą się i zapadają przy naciśnięciu GoSkin · 84 domyślne ikony scifi_dark · scifi_light Ścięte panele GoStyleBoxCut z neonową krawędzią i poświatą; znaczniki fokusu GoStyleBoxBracket GoSkinSciFi — sześciokątny joystick · domyślne ikony medieval_dark · medieval_light Kute ramy GoStyleBoxMedieval — żelazo i skóra albo pergamin — z nitami i ornamentami narożnymi w menu GoSkinMedieval · 16 grawerowanych ikon nałożonych na domyślne","",28],[1,"medieval","Średniowiecze: żelazo, skóra i pergamin",0,"medieval_dark łączy ciemne żelazo i skórę ze starym złotem. medieval_light używa pergaminu i atramentu. Oba korzystają z GoSkinMedieval, istniejących widżetów i 16 oryginalnych ikon z detalami grawerunku; ikony nawigacyjne wracają do zestawu oryginalnego. Wybierz preset, zanim utworzysz swój interfejs. Jawne nadpisania GoConfig.theme, skin czy icons nadal mają pierwszeństwo. Otwórz res://addons/gohud/examples/medieval/medieval.tscn i naciśnij F6, by zobaczyć działającą kartę postaci, sakwę i dziennik zadań. Jej przyciski przełączają warianty i otwierają szczegóły przedmiotów. Żelazo i skóra Pergamin i atrament Ramy menu mają nit i mały ornament narożny; stale widoczny HUD zachowuje spokojną krawędź. Zdrowie, mana i wytrzymałość używają wypełnień czerwonego, niebieskiego i oliwkowego. Cinzel jest ograniczony do tytułów i podtytułów; tekst główny zachowuje czcionkę gospodarza lub domyślną. Dołączona czcionka niesie swoją licencję w assets/fonts/cinzel/OFL.txt. Zestaw grawerowany przerysowuje bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword i user, a dokłada scroll oraz seal. Każda inna nazwa wraca do zestawu domyślnego, więc close i settings zachowują swoje domyślne rysunki w każdym presecie. Cinzel pokrywa pismo łacińskie; nagłówkom w innych językach daj własną czcionkę przez shape.fonts. Co zestaw testów sprawdza dla obu wariantów. Wybrana jest skórka średniowieczna; panele menu i HUD to kute ramy, z ornamentem tylko w menu; tytuły używają Cinzela, a tekst główny zachowuje odziedziczoną czcionkę; grawerowane ikony importują się jako DPITexture; prawdziwy szybki slot używa skórki; zmiana pokręteł skopiowanej skórki dociera do slotu bez ruszania presetu; a przełączenie z powrotem przywraca geometrię domyślną i sci-fi.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # Albo: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[1,"make-a-kingdom-of-your-own","Zrób własne królestwo",1,"Motywy JSON mogą dziedziczyć po innych motywach JSON. Pominięte wartości zachowują ustawienia rodzica; dziedziczenie cykliczne jest odrzucane. Wygenerowany preset zachowuje zestaw ikon rodzica. Ustawienie Efekt shape.material 0: żelazo · 1: skóra · 2: pergamin. Decyduje o znakach na powierzchni. shape.grain_alpha Krycie faktury. Użyj 0, by uzyskać czystą powierzchnię. shape.ornament_scale · shape.bevel_strength Rozmiar ornamentu narożnego w menu i siła podświetlenia fazy. shape.fonts Przypisuje role title, subtitle, caption, body i button do plików czcionek res:// wewnątrz dodatku. Pominięte role zachowują odziedziczoną czcionkę. skin.dials Promień szybkiego slotu, widoczność nitów, faktura i podświetlenie. Pełna tabela niżej wymienia każde pokrętło.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Edytuj themes/palettes/kingdom.json, a potem: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # W GDScripcie, przed utworzeniem widżetów: GoUi.use_preset(&\"kingdom\")",31],[1,"tokens","Tokeny",0,"Każdy kolor i każdy wymiar mieszka w motywie pod typem GoHud, adresowany po nazwie. Zasadą jest niepisanie liczb: nazwy idą za motywem, gdy ten zostanie podmieniony.","GoUi.color(GoTheme.ACCENT) # kolor GoUi.metric(GoTheme.GAP) # wymiar (dp) GoUi.font_size(GoTheme.ROLE_CAPTION) # rozmiar dla roli tekstu GoUi.box(GoTheme.BOX_CARD) # kopia StyleBoxa",-1],[1,"colours","Kolory",1,"Nazwa Do czego służy background Podłoga ekranu surface · surface_soft · surface_high Trzy warstwy paneli — panel, karta, uniesiona komórka border Obramowania kart i przycisków text · secondary · muted Trzy poziomy tekstu — główny, wspierający, przygaszony accent · on_accent Akcent i tekst na nim położony success · warning · danger · info Kolory tekstu statusów *_fill Te same statusy jako wypełnienie — paski i inne duże obszary scrim · shadow · track Zasłona za wyskakującymi oknami, cienie, tor paska Dlaczego istnieje *_fill. To samo znaczenie, przeciwne wymagania. warning użyty jako tekst musi być dość ciemny, by dało się go czytać na jasnym tle; użyty jako wypełnienie paska doświadczenia musi być dość jasny, by rzucał się w oczy. Jeden token nie może być jednym i drugim — pasek w jasnym motywie wyszedł brązowy. Motyw bez wariantu _fill automatycznie wraca do nazwy bazowej, więc motywy starsze niż te tokeny działają dalej.","",33],[1,"measurements-dp","Wymiary (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",33],[1,"text-roles","Role tekstu",1,"micro · compact · caption · body · button · subtitle · title — rola nazywa rozmiar, a nie przeznaczenie. „Największy tekst”, a nie „nagłówek”. Dzięki temu skala trzyma się nawet wtedy, gdy ekran użyje jej do czegoś innego.","",33],[1,"type-variations","Warianty typów",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",33],[1,"skin","Skórki — tam, gdzie motyw nie sięga",0,"Metoda Decyduje o surface_box · floating_box · overlay_box Lica kart i paneli, pływające powierzchnie, pigułki kładzione na grze albo na mapie chip_box · chip_ink Panel chipa i kolor etykiety, który pozostaje na nim czytelny slot_box · slot_ink Lica szybkich slotów i ich tekst disc_box Koło za awatarem albo plakietką alert_box · skeleton_box · segment_box Alerty w treści, wypełniacze, kontrolki segmentowe coach_ring_box Znacznik, który przewodnik stawia wokół swojego celu draw_joystick · draw_coach_pointer Rzeczy rysowane wprost — joystick i jego wskaźnik divider_color · divider_thickness · section_box Separatory i nagłówki sekcji badge_box Plakietki szybkich slotów — liczba i pozostały czas progress_fill_box · notice_box · tint_notice Wypełnienia pasków (obrysowane tam, gdzie wypełnienie nie sięga 3:1 na swoim torze) i snackbary","class_name MySkin extends GoSkin func draw_joystick(canvas: CanvasItem, center: Vector2, knob: Vector2, radius: float, knob_radius: float, ink: Color, base: Color, active: bool) -> void: # Widżet wyliczył już pozycje — tutaj dzieje się tylko rysowanie canvas.draw_circle(center, radius, Color(base, 0.4)) canvas.draw_circle(knob, knob_radius, ink)",-1],[1,"shapes-styleboxflat-cannot-make","Kształty, których StyleBoxFlat nie potrafi zrobić",1,"Klasa Co rysuje GoStyleBoxCut Ukośnie ścięte narożniki, jedna pogrubiona krawędź akcentu, zewnętrzna poświata GoStyleBoxBracket Same znaczniki narożne, pozostawiające treść niezamkniętą w ramie GoStyleBoxMedieval Kuta rama — nity, grawer w narożnikach, podświetlenie fazy oraz faktura żelaza, skóry albo pergaminu Wszystkie trzy serializują się do zasobu Theme jak każdy inny StyleBox — i to właśnie pozwala motywowi zmieniać kształt. Margines wewnętrzny dawaj przez content_margin_*. Dziedziczenie po StyleBox w GDScripcie oznacza, że _get_style_margin() nigdy nie zostaje wywołane (zmierzone na Godocie 4.7). Wypełnij wbudowane pola, inaczej treść usiądzie na obramowaniu.","",38],[1,"own","Twój własny preset — jeden plik",0,"Dodanie motywu oznaczało kiedyś ręczną edycję w czterech miejscach — palety buildera, kształtu, skórki, zasobu presetu. Jedno polecenie ustawia teraz wszystkie. Pierwsza linijka zapisuje themes/palettes/neon.json i themes/presets/neon.tres. JSON niesie każdą wartość motywu, po którym dziedziczy, wypisaną wprost, więc służy zarazem za listę tego, co możesz zmienić: usuń klucz, by zachować wartość rodzica, wpisz go, by ją nadpisać. Presety znajdowane są przez skanowanie themes/presets/, więc żaden kod rejestru się nie zmienia — lista rozwijana w ustawieniach projektu też je podchwyci.","python3 addons/gohud/tools/new_theme.py neon --from scifi_dark --title \"Neon\" python3 addons/gohud/tools/make_theme.py neon # .tres motywu + grafiki kontrolek godot --headless --path . --import # zaimportuj nowe grafiki raz GoUi.use_preset(&\"neon\") # gotowe — pokazuje się też w selektorze",-1],[1,"what-you-can-change-on-one-page","Co możesz zmienić — na jednej stronie",1,"Gdzie Co Jak from motyw rodzica dark · light · scifi_dark · medieval_dark · … albo inny motyw JSON. Pominięte klucze dziedziczą jego wartości; cykl dziedziczenia kończy się błędem palette tło · trzy powierzchnie · obramowanie · trzy tony tekstu · akcent · cztery kolory statusów · zasłona · cień · tor paska \"#RRGGBB\", kanał alfa jako \"#RRGGBB@0.35\" żywe kolory tylko do wypełnień *_vivid utrzymują nasycenie pasków nawet wtedy, gdy kolor tekstu musi pociemnieć — pomiń któryś, a builder to zgłosi czytelność nie strojona ręcznie. Tekst, obramowania, akcent i etykieta na nim są przesuwane przez buildera, aż przekroczą progi — zmień sam akcent, a kontrole i tak przejdą shape kind flat (zaokrąglone) · cut (ścięte narożniki) · medieval (kute ramy) rozmiary radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — tokeny idą za nimi, więc panele i obliczenia widżetów nigdy się nie rozjeżdżają tylko cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge tylko medieval material (0 żelazo · 1 skóra · 2 pergamin) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button przypisane do plików czcionek res:// wewnątrz dodatku skin base — rodzina dla miejsc, które kod rysuje sam (joystick, sloty, plakietki, pierścień wskazówki instruktażowej, chipy, separatory) default · scifi · medieval dials — liczby tych miejsc: szerokość i zabarwienie obramowania slotu, margines wewnętrzny plakietki, krycie chipa i alertu, szerokość i krycie pierścienia joysticka, rozmiary fazowań sci-fi, poświata i ramka narożna Każda wartość rodzica jest wypisana wprost w JSON-ie. Builder wpisuje je do themes/skins/gohud_skin_<id>.tres — żaden kod skórki nie zostaje ruszony. Dopiero po to, by zmienić same rysunki, uruchamiasz --new-skin, który tworzy szkielet podklasy GoSkin icons zestaw ikon ścieżka res:// do zasobu GoIconSet — po pominięciu zachowywana po rodzicu JSON dark · title jak pokazuje go selektor wartość logiczna · ciąg znaków","",40],[1,"every-dial","Wszystkie pokrętła",1,"Tabelę poniżej wypełnia tools/make_site.py wprost z linii @export w skryptach skórek — dodaj pokrętło albo zmień wartość domyślną, a tabela pójdzie za tym. Używaj tych nazw pod skin.dials w JSON-ie. Pokrętło, którego domyślna wartość brzmi 14, jest liczbą całkowitą, a takie, które brzmi 10.0 — zmiennoprzecinkową; wpisz w JSON-ie dowolną formę, a builder rzutuje ją na typ ze skryptu. Skórka domyślna GoSkin — 17 Pokrętło Domyślnie Co ustawia chip_fill_alpha 0.16 Krycie wypełnienia panelu chipa. chip_edge_alpha 0.45 Krycie krawędzi panelu chipa. alert_tint 0.1 Jak mocno panel alertu jest zabarwiony w stronę swojego koloru statusu. slot_tint_lit 0.24 Zabarwienie akcentem panelu szybkiego slotu w trakcie odnowienia. slot_tint_idle 0.08 Zabarwienie akcentem panelu szybkiego slotu w spoczynku. slot_border_lit 2 Szerokość obramowania szybkiego slotu (dp) w trakcie odnowienia. slot_border_idle 1 Szerokość obramowania szybkiego slotu (dp) w spoczynku. badge_pad_x 5 Poziomy margines wewnętrzny (dp) plakietki (liczba, pozostały czas). badge_pad_y 1 Pionowy margines wewnętrzny (dp) plakietki. badge_edge_alpha 0.6 Krycie krawędzi panelu plakietki. float_shadow_alpha 0.45 Krycie cienia pływających kart (wskazówka instruktażowa, karta pytania). float_shadow_size 14 Rozmycie cienia (dp) pływających kart. float_shadow_lift 4 Przesunięcie cienia pływającej karty w dół (dp). float_glow_size 10.0 Zasięg poświaty (dp) pływającego panelu, który świeci zamiast rzucać cień, jak ścięty panel sci-fi. joystick_base_alpha 0.42 Krycie dysku podstawy joysticka. joystick_ring_alpha 0.45 Krycie pierścienia joysticka. joystick_ring_width 2.0 Szerokość (dp) pierścienia joysticka. Skórka sci-fi GoSkinSciFi — 10 Pokrętło Domyślnie Co ustawia cut_chip 7.0 Rozmiar fazowania (dp) panelu chipa. cut_skeleton 5.0 Rozmiar fazowania (dp) panelu szkieletu. cut_alert 8.0 Rozmiar fazowania (dp) pola alertu. cut_segment 8.0 Rozmiar fazowania (dp) kontrolki segmentowej. cut_slot 6.0 Rozmiar fazowania (dp) panelu szybkiego slotu. cut_disc_ratio 0.24 Fazowanie awatarów i dysków = średnica × ten współczynnik. slot_glow_alpha 0.45 Krycie poświaty slotu, którego odnowienie trwa. slot_glow_size 6.0 Zasięg poświaty (dp) slotu, którego odnowienie trwa. bracket_arm 12.0 Długość ramienia (dp) ramki celowniczej wskazówki instruktażowej. bracket_thickness 2.0 Grubość linii (dp) ramki celowniczej wskazówki instruktażowej. Skórka średniowieczna GoSkinMedieval — 5 Pokrętło Domyślnie Co ustawia slot_radius 4.0 Promień narożnika (dp) średniowiecznej ramy szybkiego slotu. leather_grain_alpha 0.035 Krycie subtelnych znaków skóry wewnątrz szybkich slotów. ornament_scale 1.0 Skala metalowych zdobień w narożnikach szybkich slotów. Ramy menu używają shape.ornament_scale. bevel_strength 0.18 Siła metalowego podświetlenia wzdłuż krawędzi szybkich slotów. slot_rivets 1 Pokazuj małe metalowe nity na szybkich slotach: 0 je ukrywa, 1 pokazuje.","",40],[1,"subclass-the-skin-optional","Odziedzicz po skórce (opcjonalnie)",1,"W skórce mieszka tylko to, czego motyw i kształt nie sięgają — sześciokąt joysticka, plakietki slotów, ramka celownicza wskazówki instruktażowej. Odziedzicz po GoSkin, nadpisz wyłącznie te metody i wskaż skin w JSON-ie na ten zasób. Motyw zmieniający same kolory pomija ten krok. Kontrola pilnuje tej obietnicy. tools/check_scaffold.sh przy każdym przebiegu tworzy jednorazowy motyw — zmienia akcent, ustawia promień na 4 — i sprawdza generowanie, propagację tokenów oraz czysty wynik kontrastu, zanim go usunie. Pierwszy przebieg wykrył, że motyw ze zmienionym tylko akcentem oblewa 8 par: builder przesuwał kolory tekstu, ale akcentu używał tak, jak go zapisano. Teraz przesuwa także akcent i etykietę na nim.","",40],[1,"contrast","Czytelność się mierzy",0,"„Ładne” to kwestia gustu; „czytelne” da się zmierzyć. Blady szary tekst wygląda dobrze na dobrym monitorze i znika na telefonie w słońcu — wybieranie na oko prędzej czy później to gwarantuje. Co Wymagane Tekst główny 4.5 : 1 Duży tekst (od 24 px) 3 : 1 Obramowania i ikony w kolorze akcentu 3 : 1 Obramowania dekoracyjne 2 : 1 — WCAG nie stosuje swojej reguły 3:1 do dekoracji Sąsiadujące powierzchnie 1.12 : 1 — tyle, by karta czytała się jako oddzielona od tła","python3 addons/gohud/tools/check_contrast.py",-1],[1,"same-hue-text-on-a-same-hue-tint","Tekst w tym samym odcieniu na zabarwieniu tego samego odcienia",1,"Ta pułapka pojawiła się w tym kodzie trzy razy — przy naciśniętych przyciskach (panel akcentu, etykieta akcentu), przyciskach niebezpieczeństwa i chipach. Wygląda dobrze na próbniku i rozpada się w chwili pomiaru, bo oba dzielą odcień i przez to nie różnią się jasnością. Kolory etykiet nie są więc wybierane ręcznie. Builder motywów i GoSkin każdy z osobna przesuwają jasność — i tylko jasność — aż próg zostanie przekroczony na panelu, na którym tekst faktycznie leży. Odcień i nasycenie przeżywają, więc paleta zachowuje swój charakter, a jej zmiana zachowuje kontrast.","",44],[1,"colour-read-as-text-and-colour-painted-as-area-w","Kolor czytany jako tekst i kolor malowany jako powierzchnia chcą przeciwnych rzeczy",1,"W jasnym motywie kolor ostrzeżenia musi pociemnieć, by pozostać czytelnym jako tekst (#96500A). Gdy wypełnienie paska to dziedziczy, pasek doświadczenia robi się brązowy. Sam kolor tego nie naprawi: żółty jest z natury jasny, więc nie przekracza 3:1 nad żadnym szarym torem, a przyciemnienie toru robi jeszcze gorzej (1.52 → 1.06). Dlatego jedno zostaje oddzielone od drugiego. Kolor zostaje żywy — paleta niesie kolory tylko do wypełnień, takie jak warning_vivid. Kontrast niesie krawędź — GoSkin rysuje obrys 1 dp na każdym wypełnieniu, które nie sięga 3:1 względem swojego toru, żeby „ile tego jeszcze zostało” pozostało czytelne. Pominięcie jest zgłaszane. Bez *_vivid wypełnienie, które wyjdzie ciemne, sprawia, że builder wypisuje 막대가 칙칙하다 — 팔레트에 warning_vivid 를 더한다 (po koreańsku: „pasek jest matowy — dodaj warning_vivid do palety”). Miejsce, które kiedyś degradowało się po cichu, teraz o tym mówi.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # czytany jako tekst warning_vivid=hexc(\"F2A007\"), # malowany na pasku )",44],[1,"a-floating-panel-cannot-know-what-is-behind-it","Pływający panel nie może wiedzieć, co jest za nim",1,"HUD rysowany jest na grze — na śnieżnym polu albo w jaskini. Jeśli jego panel jest półprzezroczysty, to, co za nim, przebija przez niego i zmienia kolor panelu, ciągnąc kontrast tekstu w dół razem ze sobą. Przy 82% krycia przygaszony tekst ciemnych motywów spadał do 3.74:1 nad jasnym tłem — poniżej minimum. Dlatego półprzezroczyste panele mierzone są z czystą bielą i czystą czernią za nimi; to najgorsze, co scena gry może zaserwować. Panel HUD w dołączonych motywach jest dość nieprzezroczysty, by przejść (92%), a mimo to zachowuje szklany wygląd. Z tego samego powodu kolory ikon też nie są ustalone na sztywno. Glif szybkiego slotu był zakodowany na biało i mierzył 1.11:1 w jasnym motywie — teraz idzie za panelem, na którym leży, dokładnie tak jak etykiety. Dwa kontrolery, dwa zasięgi. check_contrast.py czyta pliki motywów; kolory, które skórka miesza w czasie działania (chipy, sloty), mierzy sekcja skin contrast zestawu testów wewnątrz Godota.","",44],[2,"surfaces","Pływające okna",0,"","",-1],[2,"gosurface-the-shell","GoSurface — powłoka",1,"Wyskakujące okna, arkusze i listy rozwijane — wszystkie używają tego jednego. Zajmuje się bezpiecznym obszarem, klawiaturą ekranową, przyklejonym nagłówkiem i stopką, przewijanym ciałem, tym, które okno jest wierzchnie, przywracaniem fokusu, własnością przycisku Wstecz i zmianą rozmiaru przeciągnięciem. Umiejscowienie Wygląda jak Do czego służy CENTER Karta na środku Potwierdzenia, ustawienia BOTTOM Arkusz wznoszący się od dołu Listy, strony zarządzania ANCHOR Karta przypięta obok kontrolki Listy rozwijane, menu kontekstowe Nie usuwa się sam. Reakcja na close_requested — ukrycie albo zwolnienie — należy do ekranu, który go posiada, bo powłoka nie może wiedzieć, dlaczego się zamyka (zapisz i zamknij czy odrzuć).","",48],[2,"gosheet-a-page-from-the-bottom","GoSheet — strona od dołu",1,"Posiada własny CanvasLayer, więc niezawodnie siedzi ponad HUD. open() czyści ciało i wyłącza przycisk Wstecz oraz przyklejone wiersze — martwy przycisk na ekranie, z którego nie ma dokąd wracać, czyta się jako zepsuty.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Ekwipunek\") sheet.toolbar().add_child(GoStyle.line_edit(\"Szukaj…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Zamknij\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",48],[2,"godialogs-confirmations-you-await","GoDialogs — potwierdzenia, na które czekasz przez await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — wszystko po treści jest opcjonalne, a alert() działa tak samo, tylko z jednym przyciskiem. Ustaw destructive dla czegoś, czego nie da się cofnąć: przycisk potwierdzenia staje się wypełnionym przyciskiem GoStyle.Tone.DANGER_SOLID. W jasnym motywie zabarwiona etykieta niebezpieczeństwa musi ciemnieć aż do czerni; wypełniony przycisk zachowuje biały tekst na czerwieni. Ton nakładany jest ponownie przy każdym wywołaniu, bo jedno okno jest używane wielokrotnie, a drugie confirm() w trakcie otwartego pierwszego zwraca od razu false. confirm_key() przyjmuje klucze tłumaczeń. Układ przycisków. action_layout to domyślnie VERTICAL (bezpieczne przy długich tłumaczeniach), HORIZONTAL dla jednego rzędu z połową szerokości na każdy, albo AUTO, które wybiera jeden rząd tylko wtedy, gdy obie etykiety mieszczą się w połowie karty w jednej linii, a poza tym układa je jedna pod drugą. action_gap to odstęp między przyciskami, a body_gap odstęp nad nimi — zrób go szerszym niż odstęp między przyciskami, żeby pytanie i wybór czytały się jako dwie części. Dla jednego okna z osobna wywołaj set_next_action_layout() przed jego otwarciem. Rząd budowany jest przy pierwszym otwarciu okna, więc GoDialogs w autoloadzie nic nie dokłada przy starcie.","if await dialogs.confirm(\"Usuń zapis\", \"Tego nie da się cofnąć.\"): delete_save()",48],[2,"goform-a-width-capped-form","GoForm — formularz z ograniczoną szerokością",1,"Gwarantuje, że etykiety u jego potomków się zawijają. Bez tego jedno długie zdanie rozciąga się w pojedynczą linię, której minimalna szerokość przekracza ekran, i boki zostają obcięte — nie da się nawet poznać, na jakim ekranie się jest. Włączanie zawijania ręcznie w każdej scenie zapomina się za każdym razem.","",48],[2,"goscroll-touch-scrolling","GoScroll — przewijanie dotykiem",1,"Włóż do środka jedną rzecz. Nagłówki i rzędy przycisków należą na zewnątrz — długa lista nie może wypychać ich poza ekran. use_panel_edge() przenosi pasek przewijania w istniejący margines wewnętrzny karty, a treść zachowuje swoje wcięcie.","",48],[2,"messages","Jak powiedzieć coś graczowi",0,"","",-1],[2,"gonotice-snackbar","GoNotice — snackbar",1,"Nigdy nie przechwytuje wejścia. Powiadomienie się czyta, a nie naciska. Nie zabiera fokusu, nie blokuje wejścia gry, a przycisk pod nim nadal się naciska. Gdy potrzebne jest potwierdzenie, użyj GoDialogs; gdy potrzebny jest wybór — GoPromptCard.","",54],[2,"gopromptcard-a-question-that-does-not-block","GoPromptCard — pytanie, które nie blokuje",1,"Pływa z jednej strony, bez zasłony. Gra działa dalej.","",54],[2,"gocoachmark-guided-tour","GoCoachMark — przewodnik po interfejsie",1,"Wskazuje prawdziwe kontrolki, jedną po drugiej. Wejście przyjmuje tylko karta, więc naciśnięcie samej podświetlonej kontrolki przesuwa przewodnik dalej — „naciśnij tutaj” staje się czynnością, a nie zdaniem. title i body mogą być kluczami tłumaczeń albo zwykłym tekstem. Krok, którego cel zniknął, zostaje pominięty.","tour.start([ {\"target\": bag_button, \"title\": \"Sakwa\", \"body\": \"Wszystko, co podniesiesz, ląduje tutaj.\"}, {\"target\": map_button, \"title\": \"Mapa\", \"body\": \"Naciśnij, by otworzyć pełną mapę.\"}, ])",54],[2,"hud","HUD",0,"","",-1],[2,"the-small-things-decide-whether-it-looks-good","O tym, czy wygląda dobrze, decydują drobiazgi",1,"Dopieszczaj duże panele, ile chcesz — w oczy i tak rzuca się zawsze coś małego: słowo przełamane na pół, ucięta poświata, ciasny slot. Cztery takie rzeczy wskazano 2026-09-13 i naprawiono je w widżetach i motywach, a nie na ekranie demo, więc każdy ekran dostaje ten sam efekt. Co się pokazało Przyczyna Naprawa Napis Done na wskazówce instruktażowej zmienił się w Don/e Przycisk z włączonym zawijaniem odejmuje szerokość swojego tekstu od minimum — ściśnij go, a złamie się w środku słowa GoStyle.fit_words(): jedno słowo nigdy się nie zawija; kilka słów zawija się, ale najdłuższe słowo zawsze się mieści — sądzone po tekście wyświetlanym, a nie po kluczu tłumaczenia, i nakładane ponownie przez formularz przy zmianie języka Poświata przycisku na pełną szerokość została ucięta pionowo po lewej Kontener przewijania przycina na swojej krawędzi, bez wyjątków. Przetrwała tylko prawa strona, dzięki rynience na pasek GoScroll pożycza margines rodzica, by wypchnąć swoją krawędź o 12 dp na zewnątrz, i oddaje go w środku — treść zostaje na miejscu Czas, ikona i liczba ustawiły się w slocie jedno pod drugim Trzy rzędy wewnątrz 48 dp Ikona duża na środku, skrót w lewym górnym rogu, liczba jako plakietka w prawym dolnym, pozostały czas jako plakietka na ikonie — panele plakietek pochodzą z badge_box() skórki Płaska lista rozwijana bez widocznego zaznaczenia Najechanie na pozycję używało panelu przycisku; znaczniki wyboru były bladą domyślną grafiką silnika Dedykowany panel najechania (miękkie zabarwienie akcentem), ta sama grafika przycisku radiowego co przy polach wyboru, wysokość pozycji dobrana pod dotyk Lista rozwijana — panel najechania i znacznik wyboru Sloty — plakietki narożne i pozostały czas (sci-fi) Daj przyciskom z samą ikoną opis przez GoStyle.icon_button(icon, action, -1, tooltip_key) — podpowiedź dla użytkowników myszy i nazwa dostępności dla czytników ekranu biorą się z tej jednej wartości. gohud rysuje podpowiedź sam: domyślna z silnika łamie tekst po jednym znaku na linię, gdy jego obliczenie szerokości idzie źle (zmierzone przy 1 dp szerokości). Karta wskazówki trzyma się z dala od stałych elementów W orientacji poziomej karta trafiała kiedyś na samą górną albo dolną krawędź — dokładnie tam, gdzie mieszkają nagłówki i elementy HUD; w demie siadała na → × nagłówka. Teraz trzyma się na wysokości swojego celu, omija każdy GoHudAnchor, który rezerwuje miejsce, a inne rzeczy do omijania przyjmuje przez keep_clear. Przesuwa się o najkrótszy dystans, który uwalnia przeszkodę, nie zasłaniając celu, i zostaje na miejscu, gdy ekran jest za mały, by uwolnić wszystko — nachodzenie jest lepsze niż znikanie. Jej głębia — żeby czytała się jako ponad stroną — pochodzi z pokręteł skórki (float_shadow_size, float_shadow_lift, float_shadow_alpha; skórki ze ściętymi narożnikami używają float_glow_size).","tour.keep_clear = [header_bar, toolbar] # stałe elementy, które nie są kotwicami",58],[2,"screens-with-a-mouse-and-a-keyboard","Ekrany z myszą i klawiaturą",1,"Palec nie ma stanu najechania. Buduj wyłącznie pod urządzenia mobilne, a dwa stany występujące tylko na komputerze zostaną niesprawdzone — i jeden z nich był zepsuty: pierścień fokusu gohud był niewidoczny na przycisku głównym. Panel miał kolor akcentu i pierścień też: 1.00:1, ten sam kolor narysowany sam na sobie. Poruszając się klawiaturą, nie dało się poznać, gdzie się jest. Od góry do dołu: zwykły · najechanie · fokus. Wypełnione przyciski dostają pierścień kontrastujący z ich panelem. Wypełnione przyciski (GoPrimaryButton, GoDangerSolidButton) używają pierścienia, który kontrastuje z ich własnym panelem — ciemnego w ciemnym motywie, białego w jasnym, ciemnej ramki celowniczej w sci-fi. Kontroler kontrastu mierzy pierścień fokusu względem panelu, na którym leży, więc reguła przeżywa zmianę palety (WCAG 2.4.11 wymaga 3:1 dla wskaźników fokusu).","",58],[2,"gohudanchor-nine-spots","GoHudAnchor — dziewięć miejsc",1,"Szanuje bezpieczny obszar i marginesy przy krawędziach. Daj mu landscape_spot, a przesunie się w orientacji poziomej — kontrolki, które w pionie siedzą na dole pośrodku, mogą trafić na dół po prawej. Po co istnieje. Pisane ręcznie dla każdego elementu HUD, kotwice i przesunięcia się rozjeżdżają: pasek zdrowia ląduje pod wycięciem kamery na urządzeniu z notchem, a przycisk sterowania siada na pasku gestów w orientacji poziomej. Ta arytmetyka mieszka w jednym miejscu. Jak trzymać treść spod HUD Gdy przewijany ekran dzieli wyświetlacz z HUD, treść wsuwa się pod niego i oba zestawy tekstu nachodzą na siebie, aż żadnego nie da się odczytać. W tym dodatku zdarzyło się to dwa razy: tekst zastępczy pola wprowadzania wyciskał się między szybkimi slotami, a gałka przełącznika w ustawieniach lądowała na pasku zdrowia. Każdy prostokąt omijany jest w tym kierunku, który kosztuje najmniej powierzchni. Pasek w prawym górnym rogu omijany jest w dół na telefonie w pionie (13% wysokości) i na bok w poziomie (21% szerokości) — omijanie go pionowo w orientacji poziomej kosztowałoby 27% ekranu. Oddany już teren odejmuje się, zanim zmierzony zostanie następny prostokąt. Elementy HUD zderzają się także ze sobą Dziewięć miejsc dzieli ekran; nie gwarantuje, że elementy miną się wzajemnie. Szeroki snackbar na górze pośrodku wylądował dokładnie na pasku zdrowia w prawym górnym rogu i zasłonił wartość — nie dało się odczytać, ile zdrowia zostało. Ustępuje tylko w pionie — przesuwanie się także na boki sprawiłoby, że wyśrodkowane powiadomienie pojawiałoby się za każdym razem gdzie indziej. I omija wyłącznie te elementy, które same nie ustępują: gdyby ustąpiły oba, w nieskończoność zamieniałyby się miejscami.","form.avoid_hud = true # omijaj każdy widoczny GoHudAnchor joystick_anchor.reserve_space = false # …poza tymi, które pojawiają się dopiero pod palcem notice_anchor.avoid_peers = true # osiada pod stałym HUD notice_anchor.reserve_space = false # i nie przesuwa strony, dopóki jest widoczny",58],[2,"gobar-health-mana-experience","GoBar — zdrowie, mana, doświadczenie",1,"Zmiany wygładzają się przez 0,18 s — pasek zdrowia, który przeskakuje, nie mówi ci, jak mocno oberwałeś. reduce_motion sprawia, że zmiana jest natychmiastowa. Duże liczby skracają się do 12.3k, więc szerokość paska nie drga, gdy cyfry przybywają i ubywają.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # token tylko do wypełnień hp.set_values(320, 500) # \"320 / 500\"",58],[2,"goslot-one-quick-slot","GoSlot — jeden szybki slot",1,"Ikona, liczba, odnowienie i skrót na jednym licu. Wieszanie plakietek na małym kółku sprawia, że każdy slot ma inną szerokość, a rząd faluje. Rozmiar widoczny i rozmiar dotyku to co innego. Ciasno upakowane sloty mają nachodzące na siebie pola dotyku 48 dp; część wspólna przypada temu slotowi, którego środek jest bliżej — powiedz im o sobie nawzajem przez touch_peers. keyboard_focus jest domyślnie wyłączony, żeby rząd ośmiu slotów nie stanął w kolejności Tab między użytkownikiem klawiatury a wszystkimi kontrolkami ustawień. Włącz go, gdy klawiatura albo pad są jedynym wejściem.","",58],[2,"gojoystick-virtual-stick","GoJoystick — wirtualny joystick",1,"Tryb Zachowanie FIXED Zawsze w tym samym miejscu — łatwo trafić bez patrzenia FOLLOW Pojawia się tam, gdzie ląduje kciuk RELATIVE Po pojawieniu się nadal podąża za kciukiem — wygodne przy długim ruchu Vector2 z sygnału moved ma długość 0–1, więc możesz przemnożyć go wprost przez prędkość; nie zmienia się wraz z rozmiarem ekranu ani DPI.","",58],[2,"goiconbutton-looks-small-presses-large","GoIconButton — wygląda na mały, naciska się duży",1,"Bezpieczny tylko dopóki jego rodzeństwo ignoruje wejście. Jeśli poszerzony obszar zakryje sąsiedni przycisk, ten przestanie odpowiadać. Przyciski z ikonami stojące obok siebie potrzebują touch_peers.","",58],[2,"factory","GoStyle — jedno miejsce, w którym powstają rzeczy",0,"Wywołaj Button.new() wprost, a margines wewnętrzny, wysokość i zawijanie rozjadą się nieznacznie z ekranu na ekran. Tego rozjazdu nie widać w przeglądzie kodu, a widać go na zrzucie ekranu. Grupa Funkcje Struktura column row wrap_row padding spacer divider responsive_grid aspect foldable Tekst label label_key line section typography Przyciski button button_key icon_button list_button list_row apply_icon style_choice_card style_chip_button style_chip_label Wprowadzanie line_edit textarea toggle checkbox slider picker select dropdown radio_group segmented choice_grid Prezentacja card chip hud_panel chip_panel avatar skeleton alert table tabs breadcrumb progress empty_state Elementy powierzchni surface box floating disc face_padding Pomocnicze form fit_words natural_width tooltip_node card_body let_input_through box() zawsze zwraca StyleBoxFlat, ponieważ wywołujący go otrzymują i dostrajają bg_color albo corner_radius. Gdy własny kształt ma przetrwać, użyj surface().","",-1],[2,"list-rows-with-a-description","Wiersze list z opisem",1,"Wiersz z drugą linią dostaje równy margines górny i dolny, luźniejszy niż wiersz jednoliniowy, a para tytuł/opis zostaje wyśrodkowana w pionie obok ikony — także wtedy, gdy kontener rozciągnie wiersz na wyższy, i po tym, jak opis zawinie się na kilka linii. Cały wiersz pozostaje jednym celem dotknięcia. Dwuliniowe wiersze, sloty i paski w przykładzie średniowiecznym — te same wywołania fabryki pod medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Strażnik Przysięgi\", _inspect, Color.TRANSPARENT, \"Miecz długi / Atak 42\", false)",66],[2,"flowing-rows","Rzędy, które się zawijają",1,"Wkładaj kontrolki do wrap_row w ich naturalnej szerokości. Przy pozostawionym zawijaniu minimalna szerokość przycisku spada do prawie niczego, a rząd wymierza po niej swoją komórkę — etykieta zapada się do jednego znaku na linię. Fabryka zapobiega temu za ciebie.","",66],[2,"never-leave-an-empty-list-empty","Nigdy nie zostawiaj pustej listy pustą",1,"Ludzie czytają pusty ekran jako zepsuty.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Jeszcze nic tu nie ma\"))",66],[2,"hooks","Haki do dziedziczenia",0,"Każde miejsce, w którym konstruowany jest widżet potomny, przechodzi przez metodę do nadpisania, więc projekt, który dziedziczy po typach gohud, może dostać swoje własne podklasy wewnątrz widżetów bez kopiowania kodu. Hak Widżet Domyślnie _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Ukrywa kartę, gdy otwarte jest okno modalne","",-1]]};
